import requests
from requests.codes import codes

def test_too_early():
    assert codes.too_early == 425
    assert codes.TOO_EARLY == 425
    assert codes['too_early'] == 425

if __name__ == "__main__":
    try:
        test_too_early()
        print("PASS")
    except AttributeError as e:
        print(f"FAIL: {e}")
    except AssertionError as e:
        print(f"FAIL: {e}")
